        )
        .unwrap();
        std::fs::write(
            dir.join(".devcontainer.json"),
            r#"{"image": "node:20"}"#,
        )
        .unwrap();

        let found = find_devcontainer_json(&dir).unwrap();
        assert!(found.ends_with(".devcontainer/devcontainer.json"));

        let _ = std::fs::remove_dir_all(&dir);
    }
}

