        .output()
        .map_err(|e| ContainerError::DockerNotFound(e.to_string()))?;

    if !output.status.success() {
        let stderr = String::from_utf8_lossy(&output.stderr).to_string();
        return Err(ContainerError::Failed {
            operation: "build".to_string(),
            name: tag.to_string(),
            stderr,
        });
    }

    Ok(tag.to_string())
