        &effective_image,
        &hints.env,
        &hints.anonymous_volumes,
    ) {
        error!("container create failed: {e}");
        return 1;
    }
    if let Err(e) = container::start(&container_name) {
        error!("container start failed: {e}");
        return 1;
    }
}
