203→                .unwrap_or_default();
204→            info!("Added shell hook to ~/{rc_name} for tmux pane interception.");
205→        }
206→        Ok(false) => {} // Already installed or unsupported shell — silent
207→        Err(e) => warn!("could not install shell hook: {e}"),
208→    }
