216→/// Create a new branch workspace for an existing repo.
217→fn cmd_create(repo_arg: Option<&str>, branch: &str) -> i32 {
218→    let mut st = match state::load() {
219→        Ok(s) => s,
220→        Err(e) => {
221→            error!("{e}");
222→            return 1;
223→        }
224→    };
225→
226→    // Resolve repo name: use --repo if provided, otherwise auto-detect from cwd
227→    let repo = match repo_arg {
228→        Some(r) => r.to_string(),
229→        None => match detect_repo_from_cwd(&st) {
230→            Some(r) => {
231→                info!("Auto-detected repo: {r}");
232→                r
233→            }
234→            None => {
235→                error!("could not detect repo from current directory");
236→                info!("Usage: dual create <branch> --repo <name>");
237→                info!("Or run from inside a repo that was added with `dual add`.");
238→                return 1;
239→            }
240→        },
241→    };
242→
243→    // Find an existing workspace for this repo
244→    let existing = st.workspaces_for_repo(&repo);
245→    if existing.is_empty() {
246→        error!("repo '{repo}' not found. Run `dual add` inside the repo first.");
247→        return 1;
248→    }
249→
250→    // Check if this branch already exists
251→    if st.has_workspace(&repo, branch) {
252→        error!("workspace {repo}/{branch} already exists");
253→        return 1;
254→    }
255→
256→    // Get URL from existing entry
257→    let url = existing[0].url.clone();
258→
259→    // Add new entry (no explicit path — will be cloned on launch)
260→    let entry = state::WorkspaceEntry {
261→        repo: repo.clone(),
262→        url,
263→        branch: branch.to_string(),
264→        path: None,
265→    };
266→
267→    if let Err(e) = st.add_workspace(entry) {
268→        error!("{e}");
269→        return 1;
270→    }
271→
272→    if let Err(e) = state::save(&st) {
273→        error!("failed to save state: {e}");
274→        return 1;
275→    }
276→
277→    let ws_id = config::workspace_id(&repo, branch);
278→    info!("Created workspace: {ws_id}");
279→    info!("Use `dual launch {ws_id}` to start.");
280→    0
