 27→/// Routing entry: subdomain → container IP.
 28→type RouteMap = HashMap<String, String>;
 29→
 30→/// Full routing state: port → (subdomain → container_ip).
 31→pub struct ProxyState {
 32→    /// Map of port → RouteMap (subdomain → container_ip).
 33→    pub routes: HashMap<u16, RouteMap>,
 34→}
 35→
 36→impl ProxyState {
 37→    /// Build routing table from workspace state and running containers.
 38→    pub fn from_state(state: &WorkspaceState) -> Self {
 39→        let mut routes: HashMap<u16, RouteMap> = HashMap::new();
 40→
 41→        for entry in state.all_workspaces() {
 42→            let container_name = config::container_name(&entry.repo, &entry.branch);
 43→
 44→            // Only route to running containers
 45→            if container::status(&container_name) != container::ContainerStatus::Running {
 46→                continue;
 47→            }
 48→
 49→            let ip = match container::get_ip(&container_name) {
 50→                Some(ip) => ip,
 51→                None => continue,
 52→            };
 53→
 54→            // Load hints to get ports
 55→            let ws_dir = state.workspace_dir(entry);
 56→            let hints = config::load_hints(&ws_dir).unwrap_or_default();
 57→
 58→            let workspace_id = config::workspace_id(&entry.repo, &entry.branch);
 59→            for &port in &hints.ports {
 60→                routes
 61→                    .entry(port)
 62→                    .or_default()
 63→                    .insert(workspace_id.clone(), ip.clone());
 64→            }
 65→        }
 66→
 67→        ProxyState { routes }
 68→    }
 69→
 70→    /// Get the container IP for a given port and subdomain.
 71→    pub fn resolve(&self, port: u16, subdomain: &str) -> Option<&str> {
 72→        self.routes
 73→            .get(&port)
 74→            .and_then(|m| m.get(subdomain))
 75→            .map(|s| s.as_str())
 76→    }
 77→
 78→    /// Get all unique ports that need listeners.
 79→    pub fn ports(&self) -> Vec<u16> {
 80→        self.routes.keys().copied().collect()
 81→    }
 82→}
 83→
 84→/// Start the reverse proxy, listening on all configured ports.
 85→pub async fn start(state: &WorkspaceState) -> Result<(), Box<dyn std::error::Error>> {
 86→    let proxy_state = ProxyState::from_state(state);
 87→    let ports = proxy_state.ports();
 88→
 89→    if ports.is_empty() {
 90→        info!("No ports configured for proxy. Add 'ports' to .dual.toml in your repo.");
 91→        info!("Example .dual.toml:");
 92→        info!("  image = \"node:20\"");
 93→        info!("  ports = [3000, 3001]");
 94→        return Ok(());
 95→    }
 96→
 97→    let proxy_state = Arc::new(proxy_state);
 98→
 99→    info!("Starting reverse proxy...");
100→    info!("Routes:");
101→    for (&port, routes) in &proxy_state.routes {
102→        for (subdomain, ip) in routes {
103→            info!("  {subdomain}.localhost:{port} → {ip}:{port}");
104→        }
105→    }
106→
107→    let mut handles = Vec::new();
108→
109→    for port in ports {
110→        let state = Arc::clone(&proxy_state);
111→        let addr = SocketAddr::from(([127, 0, 0, 1], port));
112→
113→        let listener = TcpListener::bind(addr).await?;
114→        info!("Listening on {addr}");
115→
116→        handles.push(tokio::spawn(async move {
117→            loop {
118→                let (stream, _) = match listener.accept().await {
119→                    Ok(conn) => conn,
120→                    Err(e) => {
121→                        warn!(port, "accept error: {e}");
122→                        continue;
123→                    }
124→                };
125→
126→                let state = Arc::clone(&state);
127→                let io = TokioIo::new(stream);
128→
129→                tokio::spawn(async move {
130→                    let service = service_fn(move |req| {
131→                        let state = Arc::clone(&state);
132→                        handle_request(state, port, req)
133→                    });
134→
135→                    if let Err(e) = http1::Builder::new()
136→                        .preserve_header_case(true)
137→                        .serve_connection(io, service)
138→                        .with_upgrades()
139→                        .await
140→                        && !e.to_string().contains("connection closed")
141→                    {
142→                        debug!("connection error: {e}");
143→                    }
144→                });
145→            }
146→        }));
147→    }
148→
149→    info!("Proxy running. Press Ctrl+C to stop.");
150→
151→    // Wait for all listeners (runs forever until Ctrl+C)
152→    for handle in handles {
153→        let _ = handle.await;
154→    }
155→
156→    Ok(())
157→}
