159→/// Handle a single HTTP request by proxying to the correct container.
160→async fn handle_request(
161→    state: Arc<ProxyState>,
162→    port: u16,
163→    req: Request<Incoming>,
164→) -> Result<Response<Full<Bytes>>, hyper::Error> {
165→    // Extract subdomain from Host header
166→    let host = req
167→        .headers()
168→        .get("host")
169→        .and_then(|h| h.to_str().ok())
170→        .unwrap_or("");
171→
172→    let subdomain = extract_subdomain(host);
173→    debug!(host, port, "routing request");
174→
175→    let container_ip = match subdomain.and_then(|s| state.resolve(port, s)) {
176→        Some(ip) => ip.to_string(),
177→        None => {
178→            let body = format!(
179→                "No route for host: {host}\n\nAvailable routes on port {port}:\n{}",
180→                state
181→                    .routes
182→                    .get(&port)
183→                    .map(|m| m
184→                        .keys()
185→                        .map(|s| format!("  {s}.localhost:{port}"))
186→                        .collect::<Vec<_>>()
187→                        .join("\n"))
188→                    .unwrap_or_default()
189→            );
190→            return Ok(bad_gateway(body));
191→        }
192→    };
193→
194→    // Forward the request to the container
195→    let target_uri = format!(
196→        "http://{}:{}{}",
197→        container_ip,
198→        port,
199→        req.uri()
200→            .path_and_query()
201→            .map(|pq| pq.as_str())
202→            .unwrap_or("/")
203→    );
204→
205→    // Use a TCP connection to the container
206→    let stream = match tokio::net::TcpStream::connect(format!("{container_ip}:{port}")).await {
207→        Ok(s) => s,
208→        Err(e) => {
209→            let body = format!("Cannot connect to {container_ip}:{port}: {e}");
210→            return Ok(bad_gateway(body));
211→        }
212→    };
213→
214→    let io = TokioIo::new(stream);
215→
216→    let (mut sender, conn) = match hyper::client::conn::http1::handshake(io).await {
217→        Ok(c) => c,
218→        Err(e) => {
219→            let body = format!("Handshake failed with {container_ip}:{port}: {e}");
220→            return Ok(bad_gateway(body));
221→        }
222→    };
223→
224→    // Drive the connection in the background
225→    tokio::spawn(async move {
226→        if let Err(e) = conn.await
227→            && !e.to_string().contains("connection closed")
228→        {
229→            warn!("backend connection error: {e}");
230→        }
231→    });
232→
233→    // Forward request
234→    let _ = target_uri; // URI used for logging context
235→    match sender.send_request(req).await {
236→        Ok(resp) => {
237→            // Collect the response body
238→            let (parts, body) = resp.into_parts();
239→            match body.collect().await {
240→                Ok(collected) => Ok(Response::from_parts(parts, Full::new(collected.to_bytes()))),
241→                Err(e) => {
242→                    let body = format!("Error reading response: {e}");
243→                    Ok(bad_gateway(body))
244→                }
245→            }
246→        }
247→        Err(e) => {
248→            let body = format!("Proxy error: {e}");
249→            Ok(bad_gateway(body))
250→        }
251→    }
252→}
253→
254→/// Extract subdomain from a Host header value.
255→/// "lightfast-main.localhost:3000" → Some("lightfast-main")
256→/// "localhost:3000" → None
257→/// "lightfast-main.localhost" → Some("lightfast-main")
258→fn extract_subdomain(host: &str) -> Option<&str> {
259→    // Strip port if present
260→    let host_part = host.split(':').next().unwrap_or(host);
261→
262→    // Check for .localhost suffix
263→    if let Some(subdomain) = host_part.strip_suffix(".localhost")
264→        && !subdomain.is_empty()
265→    {
266→        return Some(subdomain);
267→    }
268→
269→    None
270→}
