272→/// Get all configured URLs for workspaces.
273→pub fn workspace_urls(state: &WorkspaceState) -> Vec<(String, Vec<String>)> {
274→    let mut result = Vec::new();
275→
276→    for entry in state.all_workspaces() {
277→        let container_name = config::container_name(&entry.repo, &entry.branch);
278→        let workspace_id = config::workspace_id(&entry.repo, &entry.branch);
279→        let is_running = container::status(&container_name) == container::ContainerStatus::Running;
280→
281→        // Load hints to get ports
282→        let ws_dir = state.workspace_dir(entry);
