 81→/// Build a WorkspaceState pointing at a fixture repo.
 82→pub fn fixture_state(
 83→    workspace_root: &Path,
 84→    fixture_repo: &Path,
 85→    repo_name: &str,
 86→    branch: &str,
 87→) -> dual::state::WorkspaceState {
 88→    let mut state = dual::state::WorkspaceState::new();
 89→    state.workspace_root = Some(workspace_root.to_string_lossy().to_string());
 90→    state
 91→        .add_workspace(dual::state::WorkspaceEntry {
 92→            repo: repo_name.to_string(),
 93→            url: fixture_repo.to_string_lossy().to_string(),
 94→            branch: branch.to_string(),
 95→            path: None,
 96→        })
 97→        .unwrap();
 98→    state
 99→}
