 93→#### 3. Create devcontainer parser module
 94→**File**: `src/devcontainer.rs` (new)
 95→**Changes**: Full module with types, parsing, and path resolution
 96→
 97→```rust
 98→use serde::Deserialize;
 99→use std::collections::HashMap;
100→use std::path::{Path, PathBuf};
101→
102→use crate::config::RepoHints;
103→
104→/// Subset of devcontainer.json fields that Dual consumes.
105→/// See: https://containers.dev/implementors/json_reference/
106→#[derive(Debug, Deserialize)]
107→#[serde(rename_all = "camelCase")]
108→pub struct DevcontainerJson {
109→    /// Docker image to use (mutually exclusive with `build`)
110→    pub image: Option<String>,
111→
112→    /// Build configuration for Dockerfile-based images
113→    pub build: Option<BuildConfig>,
114→
115→    /// Ports to forward from the container
116→    pub forward_ports: Option<Vec<PortSpec>>,
117→
118→    /// Environment variables for the container
119→    pub container_env: Option<HashMap<String, String>>,
120→
121→    /// Command to run after container creation
122→    pub post_create_command: Option<CommandSpec>,
123→
124→    /// Mount configurations
125→    pub mounts: Option<Vec<MountSpec>>,
126→}
127→
128→/// Build configuration from devcontainer.json.
129→#[derive(Debug, Deserialize)]
130→pub struct BuildConfig {
131→    /// Path to Dockerfile (relative to devcontainer.json location)
132→    pub dockerfile: Option<String>,
133→
134→    /// Build context path (relative to devcontainer.json location)
135→    pub context: Option<String>,
136→
137→    /// Docker build arguments
138→    pub args: Option<HashMap<String, String>>,
139→
140→    /// Build target stage for multi-stage builds
141→    pub target: Option<String>,
142→}
143→
144→/// Port specification — devcontainer allows integers or strings.
145→#[derive(Debug, Deserialize)]
146→#[serde(untagged)]
147→pub enum PortSpec {
148→    Number(u16),
149→    String(String),
150→}
151→
152→impl PortSpec {
153→    /// Convert to u16, parsing strings as integers.
154→    pub fn to_port(&self) -> Option<u16> {
155→        match self {
156→            PortSpec::Number(n) => Some(*n),
157→            PortSpec::String(s) => s.parse::<u16>().ok(),
158→        }
159→    }
160→}
161→
162→/// Command specification — devcontainer allows string, array, or object forms.
163→#[derive(Debug, Deserialize)]
164→#[serde(untagged)]
165→pub enum CommandSpec {
166→    /// Single shell command: "pnpm install"
167→    String(String),
168→    /// Exec form: ["pnpm", "install"]
169→    Array(Vec<String>),
170→    /// Parallel commands: {"install": "pnpm install", "build": "pnpm build"}
171→    Object(HashMap<String, StringOrArray>),
172→}
173→
174→impl CommandSpec {
175→    /// Flatten to a single shell command string.
176→    /// - String: returned as-is
177→    /// - Array: joined with spaces
178→    /// - Object: values joined with " && "
179→    pub fn to_shell_command(&self) -> String {
180→        match self {
181→            CommandSpec::String(s) => s.clone(),
182→            CommandSpec::Array(arr) => arr.join(" "),
183→            CommandSpec::Object(map) => {
184→                let mut commands: Vec<&str> = map
185→                    .values()
186→                    .map(|v| match v {
187→                        StringOrArray::String(s) => s.as_str(),
188→                        StringOrArray::Array(arr) => {
189→                            // Can't return a joined string as &str easily,
190→                            // so we'll handle this differently below
191→                            ""
192→                        }
193→                    })
194→                    .collect();
195→                // Re-do with owned strings to handle array values
196→                let commands: Vec<String> = map
197→                    .values()
198→                    .map(|v| match v {
199→                        StringOrArray::String(s) => s.clone(),
200→                        StringOrArray::Array(arr) => arr.join(" "),
201→                    })
202→                    .collect();
203→                commands.join(" && ")
204→            }
205→        }
206→    }
207→}
