209→/// Value in a command object — can be string or array.
210→#[derive(Debug, Deserialize)]
211→#[serde(untagged)]
212→pub enum StringOrArray {
213→    String(String),
214→    Array(Vec<String>),
215→}
216→
217→/// Mount specification — devcontainer allows string or object forms.
218→#[derive(Debug, Deserialize)]
219→#[serde(untagged)]
220→pub enum MountSpec {
221→    /// Docker mount syntax: "type=volume,target=/workspace/node_modules"
222→    String(String),
223→    /// Structured mount object
224→    Object(MountObject),
225→}
226→
227→/// Structured mount configuration.
228→#[derive(Debug, Deserialize)]
229→#[serde(rename_all = "camelCase")]
230→pub struct MountObject {
231→    #[serde(rename = "type")]
232→    pub mount_type: Option<String>,
233→    pub source: Option<String>,
234→    pub target: String,
235→}
236→
237→const WORKSPACE_PREFIX: &str = "/workspace/";
238→
239→impl MountSpec {
240→    /// Extract anonymous volume path if this is a volume mount targeting /workspace/*.
241→    /// Returns the relative path (e.g., "node_modules" from "/workspace/node_modules").
242→    pub fn as_anonymous_volume(&self) -> Option<String> {
243→        match self {
244→            MountSpec::String(s) => {
245→                // Parse "type=volume,target=/workspace/node_modules" format
246→                let mut mount_type = None;
247→                let mut target = None;
248→                let mut has_source = false;
249→                for part in s.split(',') {
250→                    let (key, value) = part.split_once('=')?;
251→                    match key.trim() {
252→                        "type" => mount_type = Some(value.trim()),
253→                        "target" | "dst" | "destination" => target = Some(value.trim()),
254→                        "source" | "src" => has_source = true,
255→                        _ => {}
256→                    }
257→                }
258→                if mount_type == Some("volume") && !has_source {
259→                    target
260→                        .filter(|t| t.starts_with(WORKSPACE_PREFIX))
261→                        .map(|t| t[WORKSPACE_PREFIX.len()..].to_string())
262→                }
263→                None // String format parsing is best-effort
264→            }
265→            MountSpec::Object(obj) => {
266→                if obj.mount_type.as_deref() == Some("volume") && obj.source.is_none() {
267→                    if obj.target.starts_with(WORKSPACE_PREFIX) {
268→                        return Some(obj.target[WORKSPACE_PREFIX.len()..].to_string());
269→                    }
270→                }
271→                None
272→            }
273→        }
274→    }
275→}
