277→/// Resolve the path to devcontainer.json in a workspace directory.
278→///
279→/// Checks in order:
280→/// 1. `.devcontainer/devcontainer.json`
281→/// 2. `.devcontainer.json` (root)
282→///
283→/// Returns None if neither exists.
284→pub fn find_devcontainer_json(workspace_dir: &Path) -> Option<PathBuf> {
285→    let candidates = [
286→        workspace_dir.join(".devcontainer").join("devcontainer.json"),
287→        workspace_dir.join(".devcontainer.json"),
288→    ];
289→
290→    candidates.into_iter().find(|p| p.exists())
291→}
292→
293→/// Parse a devcontainer.json string into DevcontainerJson.
294→pub fn parse_devcontainer(json_str: &str) -> Result<DevcontainerJson, serde_json::Error> {
295→    serde_json::from_str(json_str)
296→}
297→
298→/// Load and parse devcontainer.json from a workspace directory.
299→/// Returns None if no devcontainer.json exists.
300→pub fn load_devcontainer(workspace_dir: &Path) -> Option<DevcontainerJson> {
301→    let path = find_devcontainer_json(workspace_dir)?;
302→    let contents = std::fs::read_to_string(&path).ok()?;
303→    parse_devcontainer(&contents).ok()
304→}
