306→/// Convert DevcontainerJson fields to RepoHints.
307→///
308→/// Maps:
309→/// - `image` → `hints.image`
310→/// - `build` → `hints.dockerfile`
311→/// - `forwardPorts` → `hints.ports`
312→/// - `containerEnv` → `hints.env`
313→/// - `postCreateCommand` → `hints.setup`
314→/// - `mounts` (volume type, /workspace/* target) → `hints.anonymous_volumes`
315→pub fn to_repo_hints(dc: &DevcontainerJson, devcontainer_dir: &Path) -> RepoHints {
316→    let mut hints = RepoHints::default();
317→
318→    // Image (mutually exclusive with build)
319→    if let Some(ref image) = dc.image {
320→        hints.image = image.clone();
321→    }
322→
323→    // Build → DockerfileBuild
324→    if let Some(ref build) = dc.build {
325→        if build.dockerfile.is_some() {
326→            hints.dockerfile = Some(crate::config::DockerfileBuild {
327→                path: build.dockerfile.clone().unwrap_or_else(|| "Dockerfile".to_string()),
328→                context: build.context.clone().unwrap_or_else(|| ".".to_string()),
329→                args: build.args.clone().unwrap_or_default(),
330→                target: build.target.clone(),
331→                // Resolve paths relative to devcontainer.json location
332→                base_dir: Some(devcontainer_dir.to_path_buf()),
333→            });
334→        }
335→    }
336→
337→    // Ports
338→    if let Some(ref ports) = dc.forward_ports {
339→        hints.ports = ports.iter().filter_map(|p| p.to_port()).collect();
340→    }
341→
342→    // Environment variables
343→    if let Some(ref env) = dc.container_env {
344→        hints.env = env.clone();
345→    }
346→
347→    // Setup command
348→    if let Some(ref cmd) = dc.post_create_command {
349→        let shell_cmd = cmd.to_shell_command();
350→        if !shell_cmd.is_empty() {
351→            hints.setup = Some(shell_cmd);
352→        }
353→    }
354→
355→    // Anonymous volumes from mounts
356→    if let Some(ref mounts) = dc.mounts {
357→        let extra_volumes: Vec<String> = mounts
358→            .iter()
359→            .filter_map(|m| m.as_anonymous_volume())
360→            .collect();
361→        if !extra_volumes.is_empty() {
362→            // Merge with defaults, dedup
363→            for vol in extra_volumes {
364→                if !hints.anonymous_volumes.contains(&vol) {
365→                    hints.anonymous_volumes.push(vol);
366→                }
367→            }
368→        }
369→    }
370→
371→    hints
372→}
