/// Write default .dual.toml with only Dual-specific fields.
/// Used by `dual add` when creating a new repo config.
pub fn write_default_dual_config(repo_root: &Path) -> Result<(), HintsError> {
    let template = r#"# Dual workspace configuration
# See: https://github.com/jeevanpillay/dual

# Path to devcontainer.json (auto-detects .devcontainer/devcontainer.json if omitted)
# devcontainer = ".devcontainer/devcontainer.json"

# Commands to route to the container (in addition to defaults)
# Default: npm, npx, pnpm, node, python, python3, pip, pip3, curl, make
# Example: extra_commands = ["cargo", "go", "ruby"]
# extra_commands = []

# Directories to isolate with anonymous Docker volumes
# These directories get their own volume so they don't sync between host/container
# Example: anonymous_volumes = ["node_modules", ".next", "target"]
# anonymous_volumes = ["node_modules"]

# Files to share across all workspaces of this repo
# These are gitignored files that should be available in every branch workspace
# [shared]
# files = [".env.local", ".vercel"]
"#;
    let hints_path = repo_root.join(HINTS_FILENAME);
    std::fs::write(&hints_path, template)
        .map_err(|e| HintsError::WriteError(hints_path, e))?;
    Ok(())
}

/// Write a default devcontainer.json with helpful defaults.
/// Used by `dual add` when creating a new repo config.
pub fn write_default_devcontainer(repo_root: &Path) -> Result<(), HintsError> {
    let dc_dir = repo_root.join(".devcontainer");
    std::fs::create_dir_all(&dc_dir)
        .map_err(|e| HintsError::WriteError(dc_dir.clone(), e))?;

    let template = r#"{
    "image": "node:20"
    // "forwardPorts": [3000],
    // "postCreateCommand": "npm install",
    // "containerEnv": {
    //     "NODE_ENV": "development"
    // }
}
"#;
    let dc_path = dc_dir.join("devcontainer.json");
    std::fs::write(&dc_path, template)
        .map_err(|e| HintsError::WriteError(dc_path, e))?;
    Ok(())
}
```

**Important note on JSON comments**: Standard JSON does not support comments. devcontainer.json uses JSONC (JSON with Comments) per the spec. `serde_json` will fail to parse JSONC. Two options:
1. Write valid JSON without comments (just `{"image": "node:20"}`).
2. Add a JSONC parser dependency.

Recommendation: Write valid JSON without comments, but include a descriptive structure. The `serde_json` crate already ignores unknown fields, so this is safe:

```json
{
    "image": "node:20"
}
```

For a richer default template, consider adding the `serde_json_lenient` crate or simply outputting a minimal valid JSON file. The simplest and cleanest approach is a minimal valid JSON.

