```rust
/// Load RepoHints from a workspace directory.
///
/// Merges configuration from two sources:
/// 1. `.dual.toml` -> DualConfig (Dual-specific: extra_commands, anonymous_volumes, shared, devcontainer path)
/// 2. `devcontainer.json` -> container config (image, ports, env, setup, dockerfile)
///
/// If no devcontainer.json exists, container config uses defaults (node:20, no ports, etc.)
pub fn load_hints(workspace_dir: &Path) -> Result<RepoHints, HintsError> {
    // 1. Load DualConfig from .dual.toml (or defaults if missing)
    let dual_config = load_dual_config(workspace_dir)?;

    // 2. Find and load devcontainer.json
    let dc_path = resolve_devcontainer_path(workspace_dir, &dual_config);
    let dc_hints = dc_path
        .and_then(|path| {
            let dir = path.parent().unwrap_or(workspace_dir);
            let contents = std::fs::read_to_string(&path).ok()?;
            let dc = crate::devcontainer::parse_devcontainer(&contents).ok()?;
            Some(crate::devcontainer::to_repo_hints(&dc, dir))
        });

    // 3. Merge: devcontainer provides container config, DualConfig provides orchestration
    Ok(merge_config(dual_config, dc_hints))
}
```

Add helper functions:

```rust
/// Load DualConfig from .dual.toml, returning defaults if file doesn't exist.
fn load_dual_config(workspace_dir: &Path) -> Result<DualConfig, HintsError> {
    let path = workspace_dir.join(HINTS_FILENAME);
    if path.exists() {
        let contents = std::fs::read_to_string(&path)
            .map_err(|e| HintsError::ReadError(path.clone(), e))?;
        let config: DualConfig = toml::from_str(&contents)
            .map_err(|e| HintsError::ParseError(path, e))?;
        Ok(config)
    } else {
        Ok(DualConfig::default())
    }
}

/// Resolve the path to devcontainer.json.
/// Uses the explicit path from DualConfig if set, otherwise auto-detects.
fn resolve_devcontainer_path(workspace_dir: &Path, config: &DualConfig) -> Option<PathBuf> {
    if let Some(ref explicit_path) = config.devcontainer {
        let path = workspace_dir.join(explicit_path);
        if path.exists() {
            return Some(path);
        }
        return None; // Explicit path set but doesn't exist
    }
    // Auto-detect
    crate::devcontainer::find_devcontainer_json(workspace_dir)
}

/// Merge DualConfig and devcontainer-derived hints into a single RepoHints.
fn merge_config(dual: DualConfig, dc_hints: Option<RepoHints>) -> RepoHints {
    let base = dc_hints.unwrap_or_default();

    // Merge anonymous_volumes: Dual config extends devcontainer mounts
    let mut anonymous_volumes = base.anonymous_volumes;
    for vol in &dual.anonymous_volumes {
        if !anonymous_volumes.contains(vol) {
            anonymous_volumes.push(vol.clone());
        }
    }

    RepoHints {
        // Container config from devcontainer.json (or defaults)
        image: base.image,
        ports: base.ports,
        setup: base.setup,
        env: base.env,
        dockerfile: base.dockerfile,
        // Dual-specific from .dual.toml
        extra_commands: dual.extra_commands,
        anonymous_volumes,
        shared: dual.shared,
    }
}
```

**Key design decision on `anonymous_volumes` merge**: The devcontainer.json `mounts` field contributes anonymous volumes (parsed via `MountSpec::as_anonymous_volume()`). The `.dual.toml` `anonymous_volumes` field also contributes. The merge takes the union, deduplicating. The default `["node_modules"]` comes from `DualConfig::default()`, and devcontainer mounts get added on top.

